#include <iostream>
#include <vector>
using namespace std;

using ll = long long;

const int MOD = 1000000007;

int modPow(int a, int e) {
    int result = 1;
    while (e > 0) {
        if (e & 1) result = (ll)result * a % MOD;
        a = (ll)a * a % MOD;
        e >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int k, pa, pb;
    cin >> k >> pa >> pb;

    int invSum = modPow((pa + pb) % MOD, MOD - 2);
    int probA = (ll)pa * invSum % MOD;
    int probB = (ll)pb * invSum % MOD;
    int extra = (ll)pa * modPow(pb, MOD - 2) % MOD;

    vector<vector<int>> dp(k + 1, vector<int>(k + 1));
    dp[1][0] = 1;

    int answer = 0;

    for (int a = 1; a < k; ++a) {
        for (int seq = 0; a + seq < k; ++seq) {
            if (dp[a][seq] == 0) continue;

            int nextProbability = (ll)dp[a][seq] * probA % MOD;
            if (a + 1 + seq >= k) {
                int value = (a + 1 + seq + (ll)extra) % MOD;
                answer = (answer + (ll)nextProbability * value) % MOD;
            } else {
                dp[a + 1][seq] = (dp[a + 1][seq] + nextProbability) % MOD;
            }

            nextProbability = (ll)dp[a][seq] * probB % MOD;
            int nextSeq = seq + a;
            if (a + nextSeq >= k) {
                int value = (a + nextSeq + (ll)extra) % MOD;
                answer = (answer + (ll)nextProbability * value) % MOD;
            } else {
                dp[a][nextSeq] = (dp[a][nextSeq] + nextProbability) % MOD;
            }
        }
    }

    cout << answer << '\n';
    return 0;
}

#include <iostream>
