using namespace std;

using ll = long long;

const int MOD = 1000000007;

int modPow(int a, int e) {
    ll result = 1;
    ll base = a;
    while (e > 0) {
        if (e & 1) result = result * base % MOD;
        base = base * base % MOD;
        e >>= 1;
    }
    return static_cast<int>(result);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int k, pa, pb;
    cin >> k >> pa >> pb;

    int invSum = modPow((pa + pb) % MOD, MOD - 2);
    int probA = static_cast<ll>(pa) * invSum % MOD;
    int probB = static_cast<ll>(pb) * invSum % MOD;
    int extra = static_cast<ll>(pa) * modPow(pb, MOD - 2) % MOD;

    vector<vector<int>> dp(k + 2, vector<int>(2 * k + 2));
    dp[1][0] = 1;

    int answer = 0;

    for (int a = 1; a <= k; ++a) {
        for (int b = 0; b <= 2 * k; ++b) {
            if (dp[a][b] == 0) continue;

            if (a + b >= k) {
                int value = (a + b + extra) % MOD;
                answer = (answer + static_cast<ll>(dp[a][b]) * value) % MOD;
            } else {
                dp[a + 1][b] =
                    (dp[a + 1][b] + static_cast<ll>(dp[a][b]) * probA) % MOD;
                dp[a][a + b] =
                    (dp[a][a + b] + static_cast<ll>(dp[a][b]) * probB) % MOD;
            }
        }
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MOD = 1000000007;

int modPow(int a, int e) {
    int result = 1;
    while (e > 0) {
        if (e & 1) result = (ll)result * a % MOD;
        a = (ll)a * a % MOD;
        e >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int k, pa, pb;
    cin >> k >> pa >> pb;

    int invSum = modPow((pa + pb) % MOD, MOD - 2);
    int probA = (ll)pa * invSum % MOD;
    int probB = (ll)pb * invSum % MOD;
    int ratio = (ll)pa * modPow(pb, MOD - 2) % MOD;

    if (k == 1) {
        cout << (1 + ratio) % MOD << '\n';
        return 0;
    }

    vector<vector<int>> dp(k + 1, vector<int>(k + 1));
    dp[1][0] = 1;

    int answer = k;

    auto transition = [&](int ni, int nj, int probability) {
        if (ni + nj >= k) {
            int value = (ni + nj - k + ratio) % MOD;
            answer = (answer + (ll)probability * value) % MOD;
        } else {
            dp[ni][nj] += probability;
            if (dp[ni][nj] >= MOD) dp[ni][nj] -= MOD;
        }
    };

    for (int i = 1; i < k; ++i) {
        for (int j = 0; i + j < k; ++j) {
            int probability = dp[i][j];
            if (probability == 0) continue;

            transition(i + 1, j, (ll)probability * probA % MOD);
            transition(i, j + i, (ll)probability * probB % MOD);
        }
    }

    cout << answer << '\n';
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

using ll = long long;

const int MOD = 1000000007;

int modPow(int base, int exponent) {
    int result = 1;
    while (exponent > 0) {
        if (exponent & 1) {
            result = static_cast<ll>(result) * base % MOD;
        }
        base = static_cast<ll>(base) * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int k, pa, pb;
    cin >> k >> pa >> pb;

    int invSum = modPow((pa + pb) % MOD, MOD - 2);
    int probA = static_cast<ll>(pa) * invSum % MOD;
    int probB = static_cast<ll>(pb) * invSum % MOD;
    int paOverPb = static_cast<ll>(pa) * modPow(pb, MOD - 2) % MOD;

    vector<vector<int>> dp(k + 1, vector<int>(k + 1));
    int answer = k % MOD;

    auto finish = [&](int cntA, int cntSeq, int probability) {
        int extra = (cntA + cntSeq - k + paOverPb) % MOD;
        answer = (answer + static_cast<ll>(probability) * extra) % MOD;
    };

    if (k <= 1) {
        finish(1, 0, 1);
    } else {
        dp[1][0] = 1;

        for (int cntA = 1; cntA < k; ++cntA) {
            for (int cntSeq = 0; cntA + cntSeq < k; ++cntSeq) {
                int current = dp[cntA][cntSeq];
                if (current == 0) continue;

                int nextAProbability =
                    static_cast<ll>(current) * probA % MOD;
                if (cntA + 1 + cntSeq >= k) {
                    finish(cntA + 1, cntSeq, nextAProbability);
                } else {
                    int &state = dp[cntA + 1][cntSeq];
                    state += nextAProbability;
                    if (state >= MOD) state -= MOD;
                }

                int nextBProbability =
                    static_cast<ll>(current) * probB % MOD;
                if (cntA + cntSeq + cntA >= k) {
                    finish(cntA, cntSeq + cntA, nextBProbability);
                } else {
                    int &state = dp[cntA][cntSeq + cntA];
                    state += nextBProbability;
                    if (state >= MOD) state -= MOD;
                }
            }
        }
    }

    cout << answer << '\n';
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

using ll = long long;

const int MOD = 1000000007;

int modPow(int base, int exponent) {
    int result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = (ll)result * base % MOD;
        base = (ll)base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int k, pa, pb;
    cin >> k >> pa >> pb;

    int probA = (ll)pa * modPow((pa + pb) % MOD, MOD - 2) % MOD;
    int probB = (ll)pb * modPow((pa + pb) % MOD, MOD - 2) % MOD;
    int ratio = (ll)pa * modPow(pb, MOD - 2) % MOD;

    int answer = k % MOD;

    if (k <= 1) {
        answer = (answer + 1 - k + ratio) % MOD;
        if (answer < 0) answer += MOD;
        cout << answer << '\n';
        return 0;
    }

    vector<vector<int>> dp(k + 1, vector<int>(k + 1));
    dp[1][0] = 1;

    for (int countA = 1; countA < k; ++countA) {
        for (int sequence = 0; countA + sequence < k; ++sequence) {
            int current = dp[countA][sequence];
            if (current == 0) continue;

            int nextProbability = (ll)current * probA % MOD;
            int nextSum = countA + 1 + sequence;

            if (nextSum >= k) {
                int value = (nextSum - k + ratio) % MOD;
                answer = (answer + (ll)nextProbability * value) % MOD;
            } else {
                dp[countA + 1][sequence] =
                    (dp[countA + 1][sequence] + nextProbability) % MOD;
            }

            nextProbability = (ll)current * probB % MOD;
            nextSum = countA + sequence + countA;

            if (nextSum >= k) {
                int value = (nextSum - k + ratio) % MOD;
                answer = (answer + (ll)nextProbability * value) % MOD;
            } else {
                dp[countA][sequence + countA] =
                    (dp[countA][sequence + countA] + nextProbability) % MOD;
            }
        }
    }

    cout << answer << '\n';
    return 0;
}

